function nameOf(code, fallback) {
  const t = tgtOf(code);
  if (t && t.name) return t.name;
  const p = S.px[code];
  if (p && p.name && p.name !== code) return p.name;
  for (let i = S.trades.length - 1; i >= 0; i--) {
    const tr = S.trades[i];
    if (tr.code === code && tr.name && tr.name !== code) return tr.name;
  }
"}]

